import vars from './vars';

const notifs = document.querySelector('.notifs');

// svgs generated by claude sonnet 5.5 medium

const ICONS = {
    [vars.NOTIF_INFO]: '<svg viewBox="0 0 16 16"><circle cx="8" cy="8" r="6.5"/><path d="M8 7.2v3.6"/><circle cx="8" cy="5" r=".4"/></svg>',
    [vars.NOTIF_WARN]: '<svg viewBox="0 0 16 16"><path d="M8 2L14.5 13.5H1.5Z"/><path d="M8 6.5v3.2"/><circle cx="8" cy="11.6" r=".4"/></svg>',
    [vars.NOTIF_ERROR]: '<svg viewBox="0 0 16 16"><circle cx="8" cy="8" r="6.5"/><path d="M5.8 5.8l4.4 4.4M10.2 5.8l-4.4 4.4"/></svg>'
};

const CLOSE_ICON = '<svg viewBox="0 0 16 16"><path d="M4 4l8 8M12 4l-8 8"/></svg>';

export default {
    showNotif(text, type = vars.NOTIF_INFO, time = 5) {
        const notif = document.createElement('div');
        notif.className = `notif ${type}`;

        const icon = document.createElement('div');
        icon.className = 'notif-icon';
        icon.innerHTML = ICONS[type];

        const theText = document.createElement('div');
        theText.className = 'notif-text';
        theText.textContent = text;

        const close = document.createElement('button');
        close.className = 'notif-close';
        close.innerHTML = CLOSE_ICON;
        close.setAttribute('aria-label', 'Close');

        notif.appendChild(icon);
        notif.appendChild(theText);
        notif.appendChild(close);
        notifs.appendChild(notif);

        setTimeout(() => notif.classList.add('show'), 10);
        setTimeout(() => this.removeNotif(notif), time * 1000);

        close.addEventListener('click', () => this.removeNotif(notif));

        return notif;
    },

    removeNotif(notif) {
        if (!notif.parentNode) {
            return;
        }

        notif.classList.remove('show');

        setTimeout(() => notif.remove(), 250);
    }
};
